create or replace TABLE LDL_DATA_PRODUCTION.CORE_DIM.T_DIM_CALENDAR_YEAR_QUARTER_2 (
	CAL_YEAR_QTR NUMBER(38,0) NOT NULL COMMENT 'The quarter of a calendar_2 year in the form YYYYn. E.g. 20211 for Q1/2021 starting on January 1st 2021 and ending on March 31st 2021.',
	CAL_YEAR NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 year as a number in the form YYYY. Eg. 2019',
	CAL_HALF_YEAR NUMBER(38,0) NOT NULL COMMENT 'The identifier for a calendar_2 half year in the form YYYYn. The first half year is from January to June, the second half year from July to December. E.g. 20211 for the first half year of 2021.',
	CAL_YEAR_QTR_NAME VARCHAR(100) NOT NULL COMMENT 'The text which is displayed for the quarter of the calendar_2 year in reports, in group language, i.e. German. E.g. Q1/2021 for the first quarter of the calendar_2 year 2021.',
	CAL_YEAR_QTR_NAME_DE VARCHAR(100) COMMENT 'The text which is displayed for the quarter of the calendar_2 year in reports, in German. E.g. Q1/2021 for the first quarter of the calendar_2 year 2021.',
	CAL_YEAR_QTR_NAME_EN VARCHAR(100) COMMENT 'The text which is displayed for the quarter of the calendar_2 year in reports, in English. E.g. Q1/2021 for the first quarter of the calendar_2 year 2021.',
	QTR_OF_CAL_YEAR NUMBER(38,0) COMMENT 'The number of the quarter within the calendar_2 year. E.g. 3 for Q3/2021.',
	CAL_YEAR_QTR_BEGIN_MONTH NUMBER(38,0) NOT NULL COMMENT 'The first (calendar_2) month (inclusive) of the calendar_2 year quarter as a number in the form YYYYMM. Eg. 202101.',
	CAL_YEAR_QTR_END_MONTH NUMBER(38,0) NOT NULL COMMENT 'The last (calendar_2) month (inclusive) of the calendar_2 year quarter as a number in the form YYYYMM. Eg. 202103.',
	CAL_YEAR_QTR_BEGIN_PART_WEEK NUMBER(38,0) NOT NULL COMMENT 'The first partial week (inclusive) of the calendar_2 year quarter as a number in the form YYYYWWn. Eg. 2021011.',
	CAL_YEAR_QTR_END_PART_WEEK NUMBER(38,0) NOT NULL COMMENT 'The last partial week (inclusive) of the calendar_2 year quarter as a number in the form YYYYWWn. Eg. 2021131.',
	CAL_YEAR_QTR_BEGIN_DT DATE NOT NULL COMMENT 'The first day (inclusive) of the calendar_2 year quarter as a conventional calendar_2 date in the form ''YYYY-MM_2-DD''. Eg. ''2021-01-01''.',
	CAL_YEAR_QTR_END_DT DATE NOT NULL COMMENT 'The first day (inclusive) of the calendar_2 year quarter as a conventional calendar_2 date in the form ''YYYY-MM_2-DD''. Eg. ''2021-03-31''. ',
	CAL_YEAR_QTR_WEEK_CNT NUMBER(38,0) COMMENT 'The number of weeks that this calendar_2 year quarter contains. If a week spans two quarters, it is counted for the quarter, in which it has at least four days.',
	CAL_YEAR_QTR_PART_WEEK_CNT NUMBER(38,0) COMMENT 'The number of partial weeks that this calendar_2 year quarter contains.',
	CAL_YEAR_QTR_DAY_CNT NUMBER(38,0) COMMENT 'The number of days that this calendar_2 year quarter contains.',
	PREV_1Y_CAL_YEAR_QTR NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 year quarter one year ago as a number in the form YYYYn. Eg. 20201, if the current quarter is 20211.',
	PREV_2Y_CAL_YEAR_QTR NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 year quarter two years ago as a number in the form YYYYn. Eg. 20191, if the current quarter is 20211.',
	PREV_3Y_CAL_YEAR_QTR NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 year quarter three years ago as a number in the form YYYYn. Eg. 20181, if the current quarter is 20211.',
	PREV_4Y_CAL_YEAR_QTR NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 year quarter four years ago as a number in the form YYYYn. Eg. 20171, if the current quarter is 20211.',
	PREV_5Y_CAL_YEAR_QTR NUMBER(38,0) NOT NULL COMMENT 'The calendar_2 year quarter five years ago as a number in the form YYYYn. Eg. 20161, if the current quarter is 20211.',
	CURR_CAL_YEAR_QTR_FG BOOLEAN NOT NULL COMMENT 'This indicator is set for the current quarter of the calendar_2 year.',
	CAL_YEAR_QTR_OFFSET NUMBER(38,0) COMMENT 'The difference in calendar_2 year quarters between this calendar_2 year quarter and the current calendar_2 year quarter. So if the current quarter is Q1/2021 then the offset is 0 for Q1/2021, -1 for Q4 2024 and +1 for Q2 2021.',
	CAL_HALF_YEAR_OFFSET NUMBER(38,0) COMMENT 'The difference in calendar_2 half years between the calendar_2 half year to which this quarter belongs, and the current calendar_2 half year. So if the current half year is 20211 then the offset is 0 for 20211, -1 for 20202 and +1 for 20212.',
	CAL_YEAR_OFFSET NUMBER(38,0) COMMENT 'The difference in years between the calendar_2 year to which this quarter belongs, and the current calendar_2 year. So if the current year is 2019 then the offset is 0 for 2019, -1 for 2018 and +1 for 2020.',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created or last updated.',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier of the batch load which has done the last update to this record. (Closing a record in history without updating any payload columns does not trigger an update of the dwh_load_id.)',
	DWH_NODE_CD VARCHAR(20) NOT NULL COMMENT 'The code for the source system (or slice of source system) from which this record was loaded.',
	constraint PK_T_DIM_CALENDAR_YEAR_QUARTER primary key (CAL_YEAR_QTR)
)COMMENT='The quarter of a calendar_2 year, e.g. Q1/2021 starting on January 1st 2021 and ending on March 31st 2021.'
;